public class MembershipBackfillMapper {private final Map<String,Integer> limits;public MembershipBackfillMapper(Map<String,Integer> l){limits=new HashMap<>();l.forEach((k,v)->limits.put(normalize(k),v));}public MembershipBackfillCandidate plan(LegacyMembershipRow r){if(r.id()==null||r.id()<=0||r.name()==null||r.name().isBlank())throw new IllegalArgumentException("Invalid legacy membership");String code=normalize(r.name());return new MembershipBackfillCandidate(r.id(),code,r.name(),limits.getOrDefault(code,0));}public MembershipBackfillAssignmentCandidate assignment(LegacyUserMembershipRow r){if(r.userId()==null||r.userId()<=0||r.membershipId()==null||r.membershipId()<=0)throw new IllegalArgumentException("Invalid legacy assignment");return new MembershipBackfillAssignmentCandidate(r.userId(),r.membershipId());}private String normalize(String value){return value.trim().toLowerCase(Locale.ROOT);}}
